/* The loading screen (main.c fm1_main / boot_step): the Matryoshka logo and wordmark (splash_art.h, generated by
 * tools/gen_splash.py, const = in flash), what is being loaded, a bar and the version. Also drawn by the host preview
 * (firmware/test/ui_preview.c, page 9). Needs lcd_fill / lcd_blit / lcd_sync, text5x7, the C_* colours (ui.c) and
 * lcd_line, which serves as the row buffer: the LCD's DMA reads only RAM, the art stays in flash. */
#include "splash_art.h"

#define SPLASH_LOGO_Y 4u
#define SPLASH_WORD_Y 151u
#define SPLASH_LINE_Y 204u                      /* the LOADING line */
#define SPLASH_BAR_Y 215u
#define SPLASH_BAR_X 12u
#define SPLASH_BAR_W 216u
#define SPLASH_VER_Y 226u

/* one image centred at row y: decode a row of runs into lcd_line, send it, next row (runs carry across rows) */
static void splash_art(uint32_t y, const splash_art_t *a)
{
    uint32_t x = (240u - a->w) / 2u, at = 0, run = 0, i, j;
    uint16_t c = 0;
    for (j = 0; j < a->h; j++) {
        lcd_sync();                             /* the last row may still be on its way out of the buffer */
        for (i = 0; i < a->w; i++) {
            if (!run) {
                uint8_t b = at < a->len ? a->rle[at++] : 0u;
                uint16_t v = a->pal[b >> 4];
                c = (uint16_t)((v >> 8) | (v << 8));          /* the LCD takes big endian */
                run = (b & 15u) + 1u;
                if (run == 16u && at < a->len)
                    run += a->rle[at++];
            }
            lcd_line[i] = c;
            run--;
        }
        lcd_blit(x, y + j, a->w, 1, lcd_line);
    }
}

static void splash_draw(void)
{
    lcd_fill(0, 0, 240, 240, C_BG);
    splash_art(SPLASH_LOGO_Y, &SPLASH_LOGO);
    splash_art(SPLASH_WORD_Y, &SPLASH_WORD);
    text5x7(SPLASH_BAR_X, SPLASH_VER_Y, FELUCCA_VERSION, 1, C_DIM, C_BG);
}

static void splash_line(const char *s)          /* s: at most 36 characters, padded by the caller */
{
    text5x7(SPLASH_BAR_X, SPLASH_LINE_Y, s, 1, C_FG, C_BG);
}

static void splash_bar(uint32_t w)              /* w: 0..SPLASH_BAR_W px done */
{
    if (w > SPLASH_BAR_W)
        w = SPLASH_BAR_W;
    lcd_fill(SPLASH_BAR_X, SPLASH_BAR_Y, w, 6, C_ACC);
    lcd_fill(SPLASH_BAR_X + w, SPLASH_BAR_Y, SPLASH_BAR_W - w, 6, 0x2104u);
}
